package com.ateliercampus.dao;
import com.ateliercampus.model.Atelier; import java.sql.*; import java.time.LocalDateTime; import java.util.*;
public class AtelierDao {
 private Atelier map(ResultSet r)throws SQLException{ Atelier a=new Atelier();a.setId(r.getLong("id"));a.setTitre(r.getString("titre"));a.setDescription(r.getString("description"));a.setDateHeure(r.getTimestamp("date_heure").toLocalDateTime());a.setCapacite(r.getInt("capacite"));return a;}
 public List<Atelier> list(String q)throws SQLException{List<Atelier> x=new ArrayList<>();try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM Atelier WHERE LOWER(titre) LIKE LOWER(?) ORDER BY date_heure")){p.setString(1,"%"+(q==null?"":q)+"%");try(ResultSet r=p.executeQuery()){while(r.next())x.add(map(r));}}return x;}
 public Atelier find(long id)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM Atelier WHERE id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}}
 public int countConfirmed(long id)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM Inscription WHERE atelier_id=? AND statut='CONFIRMEE'")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}}
 public void save(Atelier a)throws SQLException{try(Connection c=Database.getConnection()){if(a.getId()==null){try(PreparedStatement p=c.prepareStatement("INSERT INTO Atelier(titre,description,date_heure,capacite) VALUES(?,?,?,?)")){bind(p,a);p.executeUpdate();}return;}c.setAutoCommit(false);try{try(PreparedStatement lock=c.prepareStatement("SELECT id FROM Atelier WHERE id=? FOR UPDATE")){lock.setLong(1,a.getId());try(ResultSet r=lock.executeQuery()){if(!r.next())throw new SQLException("Atelier introuvable.");}}try(PreparedStatement count=c.prepareStatement("SELECT COUNT(*) FROM Inscription WHERE atelier_id=? AND statut='CONFIRMEE'")){count.setLong(1,a.getId());try(ResultSet r=count.executeQuery()){r.next();if(a.getCapacite()<r.getInt(1))throw new SQLException("La capacité ne peut pas être inférieure aux inscriptions confirmées.");}}try(PreparedStatement p=c.prepareStatement("UPDATE Atelier SET titre=?,description=?,date_heure=?,capacite=? WHERE id=?")){bind(p,a);p.setLong(5,a.getId());p.executeUpdate();}c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
 private void bind(PreparedStatement p,Atelier a)throws SQLException{p.setString(1,a.getTitre());p.setString(2,a.getDescription());p.setTimestamp(3,Timestamp.valueOf(a.getDateHeure()));p.setInt(4,a.getCapacite());}
 public void delete(long id)throws SQLException{try(Connection c=Database.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement lock=c.prepareStatement("SELECT id FROM Atelier WHERE id=? FOR UPDATE")){lock.setLong(1,id);try(ResultSet r=lock.executeQuery()){if(!r.next())throw new SQLException("Atelier absent.");}}try(PreparedStatement d=c.prepareStatement("DELETE FROM Inscription WHERE atelier_id=? AND statut='ANNULEE'")){d.setLong(1,id);d.executeUpdate();}try(PreparedStatement p=c.prepareStatement("DELETE FROM Atelier WHERE id=? AND NOT EXISTS(SELECT 1 FROM Inscription WHERE atelier_id=? AND statut='CONFIRMEE')")){p.setLong(1,id);p.setLong(2,id);if(p.executeUpdate()==0)throw new SQLException("Suppression refusée : confirmations existantes.");}c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}}
}
